package org.mixxx;

import java.util.concurrent.CountDownLatch;
import java.util.concurrent.TimeUnit;
import java.util.function.Consumer;

// Autonomously generated by an AI agent.
// Owns an asynchronous open result until a waiting caller takes it. A result
// arriving after a timeout or interruption is closed through the discard hook.
// End of comment autonomously generated by an AI agent.
final class PendingMidiOpen<T> {
    private final CountDownLatch ready = new CountDownLatch(1);
    private final Consumer<T> discard;
    private boolean completed;
    private T result;

    PendingMidiOpen(Consumer<T> discard) {
        this.discard = discard;
    }

    void complete(T value) {
        boolean keep;
        synchronized (this) {
            keep = !completed;
            if (keep) {
                completed = true;
                result = value;
            }
        }
        if (!keep && value != null) {
            discard.accept(value);
        }
        ready.countDown();
    }

    T await(long timeoutMillis) throws InterruptedException {
        try {
            if (!ready.await(timeoutMillis, TimeUnit.MILLISECONDS)) {
                cancel();
                return null;
            }
        } catch (InterruptedException e) {
            cancel();
            throw e;
        }
        synchronized (this) {
            T value = result;
            result = null;
            return value;
        }
    }

    void cancel() {
        T value;
        synchronized (this) {
            completed = true;
            value = result;
            result = null;
        }
        if (value != null) {
            discard.accept(value);
        }
        ready.countDown();
    }
}
